function validUtf8(data) {
  const bits = data.map(value => value.toString(2).padStart(8, '0'));
  let i = 0;
  while (i < bits.length) {
    let length;
    if (bits[i].startsWith('0')) length = 1;
    else if (bits[i].startsWith('110')) length = 2;
    else if (bits[i].startsWith('1110')) length = 3;
    else if (bits[i].startsWith('11110')) length = 4;
    else return false;
    if (i + length > bits.length) return false;
    for (let k = 1; k < length; k++) if (!bits[i + k].startsWith('10')) return false;
    i += length;
  }
  return true;
}

