function generate(rand, size) {
  const target = size === 'large' ? 2000 : 1 + Math.floor(rand() * 8);
  const bits = count => Math.floor(rand() * (1 << count));
  if (size === 'small' && rand() < 0.1) return [Array.from({ length: target }, () => Math.floor(rand() * 256))];
  const data = [];
  while (data.length < target) {
    const length = 1 + Math.floor(rand() * 4);
    if (length === 1) {
      data.push(bits(7));
      continue;
    }
    data.push(((0xff << (8 - length)) & 0xff) | bits(7 - length));
    for (let k = 1; k < length; k++) data.push(0x80 | bits(6));
  }
  const r = rand();
  if (r < 0.45) return [data];
  const at = Math.floor(rand() * data.length);
  if (r < 0.7) data[at] = Math.floor(rand() * 256);
  else if (r < 0.85 && data.length > 1) data.pop();
  else data.splice(at, 0, Math.floor(rand() * 256));
  return [data];
}
